def find_background(grid):
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    return max(counts, key=lambda x: counts[x])

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    bg = find_background(grid)
    output = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 7:
                nr, nc = r + 1, c - 1
                for i in range(3):
                    if nr < rows and nc >= 0 and output[nr][nc] == bg:
                        output[nr][nc] = 7
                        nr += 1
                        nc -= 1

    return output

