def transform_v3(grid):
    count = {}
    for row in grid:
        for x in row:
            count[x] = count.get(x, 0) + 1
    bg = max(count, key=lambda x: count[x])

    output = [row[:] for row in grid]

    rows, cols = len(grid), len(grid[0])

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 7:
                # Down-right (+1, +1) extension
                nr, nc = r + 1, c + 1
                while nr < rows and nc < cols:
                    if output[nr][nc] == 7:
                        break  # Found another 7, direction is this one
                    if output[nr][nc] != bg and output[nr][nc] != 7:
                        break  # Blocked by non-bg
                    output[nr][nc] = 7
                    nr += 1
                    nc += 1

    return output

